class Solution {
public:
    int maximumMinutes(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<int>> fire(m, std::vector<int>(n, 1e9));
        std::queue<std::pair<int, int>> q;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 1) {
                    fire[r][c] = 0;
                    q.push({r, c});
                }
            }
        }
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.empty()) {
            auto [r, c] = q.front(); q.pop();
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 0) {
                    if (fire[nr][nc] > fire[r][c] + 1) {
                        fire[nr][nc] = fire[r][c] + 1;
                        q.push({nr, nc});
                    }
                }
            }
        }
        auto canEscape = [&](int wait) {
            if (fire[0][0] <= wait) return false;
            std::vector<std::vector<bool>> vis(m, std::vector<bool>(n, false));
            vis[0][0] = true;
            std::queue<std::tuple<int, int, int>> pq;
            pq.push({0, 0, wait});
            while (!pq.empty()) {
                auto [r, c, t] = pq.front(); pq.pop();
                if (r == m - 1 && c == n - 1) return true;
                for (auto& d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 0 && !vis[nr][nc]) {
                        int arrival = t + 1;
                        if (nr == m - 1 && nc == n - 1) {
                            if (arrival <= fire[nr][nc]) {
                                vis[nr][nc] = true;
                                pq.push({nr, nc, arrival});
                            }
                        } else {
                            if (arrival < fire[nr][nc]) {
                                vis[nr][nc] = true;
                                pq.push({nr, nc, arrival});
                            }
                        }
                    }
                }
            }
            return false;
        };
        int lo = 0, hi = m * n, ans = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (canEscape(mid)) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        if (ans == -1) return -1;
        if (canEscape(1e9)) return 1e9;
        return ans;
    }
};

class Solution {
    public int maximumMinutes(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] fire = new int[m][n];
        for (int[] row : fire) java.util.Arrays.fill(row, (int) 1e9);
        java.util.Queue<int[]> q = new java.util.LinkedList<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    fire[r][c] = 0;
                    q.offer(new int[]{r, c});
                }
            }
        }
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int[] cell = q.poll();
            int r = cell[0], c = cell[1];
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 0) {
                    if (fire[nr][nc] > fire[r][c] + 1) {
                        fire[nr][nc] = fire[r][c] + 1;
                        q.offer(new int[]{nr, nc});
                    }
                }
            }
        }
        int lo = 0, hi = m * n, ans = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (canEscape(grid, fire, m, n, mid, dirs)) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        if (ans == -1) return -1;
        if (canEscape(grid, fire, m, n, (int) 1e9, dirs)) return (int) 1e9;
        return ans;
    }

    private boolean canEscape(int[][] grid, int[][] fire, int m, int n, int wait, int[][] dirs) {
        if (fire[0][0] <= wait) return false;
        boolean[][] vis = new boolean[m][n];
        vis[0][0] = true;
        java.util.Queue<int[]> q = new java.util.LinkedList<>();
        q.offer(new int[]{0, 0, wait});
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], t = cur[2];
            if (r == m - 1 && c == n - 1) return true;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 0 && !vis[nr][nc]) {
                    int arrival = t + 1;
                    if (nr == m - 1 && nc == n - 1) {
                        if (arrival <= fire[nr][nc]) {
                            vis[nr][nc] = true;
                            q.offer(new int[]{nr, nc, arrival});
                        }
                    } else {
                        if (arrival < fire[nr][nc]) {
                            vis[nr][nc] = true;
                            q.offer(new int[]{nr, nc, arrival});
                        }
                    }
                }
            }
        }
        return false;
    }
}

